#!/usr/bin/env python3
"""Audit one frozen matched-disturbance roll run or observe-only rehearsal."""
import argparse,csv,json,math,sys
from pathlib import Path
import numpy as np
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT));sys.path.insert(0,str(ROOT/'scripts'))
from design_rich_r3_roll_lqr_disturbance import disturbance
from lqr.discrete_cascade_roll_lqr import COMMAND_LIMIT,SLEW_LIMIT,DiscreteCascadeRollLQR
from run_rich_r3_roll_dualrate_xp12 import start_reasons
def main():
 p=argparse.ArgumentParser();p.add_argument('csv',type=Path);p.add_argument('--mode',choices=('lqr','baseline'),required=True);p.add_argument('--require-engaged',action='store_true');a=p.parse_args();rows=list(csv.DictReader(a.csv.open(newline='')));assert rows,'empty log';t=np.array([float(r['t_s']) for r in rows]);dt=np.diff(t);d=np.array([float(r['disturbance_command']) for r in rows]);expected=np.array([disturbance(x) for x in t]);sent=np.array([float(r['sent_roll_perturbation']) for r in rows]);selected=np.array([float(r['selected_roll_command'])-float(r['yoke_roll_bias']) for r in rows]);updates=np.array([int(r['fallback_update']) for r in rows],bool);fb=np.array([float(r['fallback_roll_command']) for r in rows]);held=np.ones(len(rows),bool);held[1:]=updates[1:]|np.isclose(fb[1:],fb[:-1],atol=1e-15);latched=np.array([int(r['fallback_latched']) for r in rows],bool);first={k:float(rows[0][k]) for k in ('altitude_m','ias_kts','pitch_deg','roll_deg','p_deg_s','q_deg_s','r_deg_s','art_stab_on','override_roll','override_pitch','paused','sim_speed','replay')};reasons=start_reasons(first);engaged=all(r['engaged']=='1' and r['controls_sent']=='1' for r in rows);runtime=DiscreteCascadeRollLQR();replay=[runtime.update(float(r['p_error_deg_s']),float(r['total_roll_perturbation']),float(r['yoke_roll_perturbation'])) for r in rows];replay_error=max(abs(float(rows[i]['lqr_command_perturbation'])-x['command']) for i,x in enumerate(replay));checks={'rows':len(rows)>=1040,'rate':len(dt)>0 and 34<=1/float(dt.mean())<=36,'gap':float(dt.max())<=.071428572,'updates':297<=int(updates.sum())<=303,'held':np.all(held),'mode':all(r['controller_mode']==a.mode for r in rows),'waveform':np.max(np.abs(d-expected))<=1e-15,'selection':np.max(np.abs(selected-sent))<=1e-15,'sent_magnitude':np.max(np.abs(sent))<=COMMAND_LIMIT+1e-15,'sent_slew':np.max(np.abs(np.diff(np.r_[0.,sent])))<=SLEW_LIMIT+1e-15,'replay':replay_error<=1e-15,'no_latch':not latched[-1] and np.all(np.diff(latched.astype(int))>=0),'start':not reasons,'engagement':engaged if a.require_engaged else not engaged,'restored':rows[-1]['restored_roll_override']=='0' and rows[-1]['restored_pitch_override']=='0','live':all(float(r['paused'])==0 and float(r['sim_speed'])==1 and float(r['replay'])==0 for r in rows),'safe':all(abs(float(r['pitch_deg']))<=10 and abs(float(r['roll_deg']))<=10 and max(abs(float(r[k])) for k in ('p_deg_s','q_deg_s','r_deg_s'))<=20 for r in rows),'finite':all(math.isfinite(float(v)) for r in rows for k,v in r.items() if k not in ('fallback_reason','controller_mode'))};checks={k:bool(v) for k,v in checks.items()};out={'file':str(a.csv),'mode':a.mode,'rows':len(rows),'effective_hz':1/float(dt.mean()),'max_gap_s':float(dt.max()),'peak_sent_command':float(np.max(np.abs(sent))),'max_sent_slew':float(np.max(np.abs(np.diff(np.r_[0.,sent])))),'waveform_error':float(np.max(np.abs(d-expected))),'checks':checks,'pass':all(checks.values())};print(json.dumps(out,indent=2));raise SystemExit(0 if out['pass'] else 1)
